public final class EquipmentGameTests implements FabricGameTest {
 private static final Map<UUID,BlockPos> DENIED=new HashMap<>();
 static{PlayerBlockBreakEvents.BEFORE.register((level,p,pos,state,entity)->!pos.equals(DENIED.get(p.getUUID())));}
 private static ServerPlayer player(GameTestHelper h){var cookie=net.minecraft.server.network.CommonListenerCookie.createInitial(new com.mojang.authlib.GameProfile(UUID.randomUUID(),"equipment-test"),false);var p=new ServerPlayer(h.getLevel().getServer(),h.getLevel(),cookie.gameProfile(),cookie.clientInformation());var c=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(c);h.getLevel().getServer().getPlayerList().placeNewPlayer(c,p,cookie);p.setPos(h.absolutePos(new BlockPos(3,3,3)).getCenter());p.setGameMode(GameType.SURVIVAL);return p;}
 private static void remove(ServerPlayer p){DENIED.remove(p.getUUID());p.getServer().getPlayerList().remove(p);p.discard();}
 private static void equip(ServerPlayer p,boolean haint){Item[] gear=haint?new Item[]{CatalogItems.HAINT_GARB_HELMET,CatalogItems.HAINT_GARB_CHESTPLATE,CatalogItems.HAINT_GARB_LEGGINGS,CatalogItems.HAINT_GARB_BOOTS}:new Item[]{CatalogItems.GHOST_GARB_HELMET,CatalogItems.GHOST_GARB_CHESTPLATE,CatalogItems.GHOST_GARB_LEGGINGS,CatalogItems.GHOST_GARB_BOOTS};EquipmentSlot[] slots={EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET};for(int i=0;i<4;i++)p.setItemSlot(slots[i],new ItemStack(gear[i]));EquipmentRuntime.tick(p);}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void garb_phases_and_native_air_exhaustion_still_drowns(GameTestHelper h){var p=player(h);try{
  for(int i=0;i<65;i++)p.tick();equip(p,false);var level=h.getLevel();var at=p.blockPosition();for(int x=-1;x<4;x++)for(int z=-1;z<=1;z++)level.setBlockAndUpdate(at.offset(x,-1,z),Blocks.STONE.defaultBlockState());for(int y=0;y<4;y++)level.setBlockAndUpdate(at.offset(1,y,0),Blocks.STONE.defaultBlockState());
  double x=p.getX();p.move(MoverType.SELF,new Vec3(1,0,0));h.assertTrue(p.getX()>x+.9,"Full Ghost set passes through walls");h.assertTrue(GhostGarbBreathing.headInsideWall(p),"Head collision includes stone");
  p.setAirSupply(300);p.baseTick();h.assertTrue(p.getAirSupply()==299,"Wall uses native underwater air consumption");p.setAirSupply(-19);p.invulnerableTime=0;float health=p.getHealth();p.baseTick();h.assertTrue(p.getHealth()<health,"Exhausted wall air deals real drowning damage through garb");
  h.assertFalse(CombatRules.allowed(p,p.damageSources().generic()),"Mundane damage blocked");h.assertTrue(CombatRules.allowed(p,p.damageSources().magic()),"Magic passes intangibility");h.assertTrue(CombatRules.allowed(p,p.damageSources().drown()),"Ordinary drowning also passes intangibility");h.assertTrue(CombatRules.allowed(p,p.damageSources().fellOutOfWorld()),"Void still damages garb");
  double y=p.getY();p.move(MoverType.SELF,new Vec3(0,1,0));h.assertTrue(p.getY()>y+.9,"Player rises through ceiling");
  p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);EquipmentRuntime.tick(p);h.assertFalse(IntangibleEntities.isIntangible(p),"Removing one piece removes defenses immediately");p.setAirSupply(100);p.baseTick();h.assertTrue(p.getAirSupply()>100,"Air refills after phasing ends");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void haint_jump_mixed_sets_and_protection_gate(GameTestHelper h){var p=player(h);try{
  double base=p.getAttributeValue(Attributes.JUMP_STRENGTH);equip(p,true);h.assertTrue(Math.abs(p.getAttributeValue(Attributes.JUMP_STRENGTH)-base-.3)<.0001,"Haint adds native jump strength");p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(CatalogItems.SPECTRALITE_HAINT_CHESTPLATE));EquipmentRuntime.tick(p);h.assertTrue(EquipmentRuntime.fullHaint(p),"Combined pieces count toward Haint full set");
  p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.POISON,100));h.assertTrue(EquipmentRuntime.preventHaunting(p),"A rolled negative haunt is blocked and emits its gear notice");h.assertTrue(p.hasEffect(net.minecraft.world.effect.MobEffects.POISON),"Ordinary poison is not silently cleansed by gear");
  p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(CatalogItems.GHOST_GARB_HELMET));EquipmentRuntime.tick(p);h.assertTrue(EquipmentRuntime.fullGarb(p)&&!EquipmentRuntime.fullHaint(p),"Mixed Ghost/Haint phases but loses full Haint jump");h.assertTrue(Math.abs(p.getAttributeValue(Attributes.JUMP_STRENGTH)-base)<.0001,"Jump modifier removed without leaving stale bonus");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void bloodstone_void_scaling_and_exact_chunk_pickaxe_repair(GameTestHelper h){var p=player(h);try{
  var tool=new ItemStack(CatalogItems.BLOODSTONE_PICKAXE);p.setItemInHand(InteractionHand.MAIN_HAND,tool);PlayerHauntManager.setTier(p,HauntTier.NATURAL);EquipmentRuntime.tick(p);double natural=p.getAttributeValue(Attributes.ATTACK_DAMAGE);PlayerHauntManager.setTier(p,HauntTier.VOID);EquipmentRuntime.tick(p);h.assertTrue(Math.abs(p.getAttributeValue(Attributes.ATTACK_DAMAGE)-natural*.9)<.001,"Void power below diamond baseline");h.assertTrue(Math.abs(EquipmentRuntime.mining(p,10)-9)<.001,"Void mining speed also scales down");
  tool.setDamageValue(tool.getMaxDamage()/2);h.assertTrue(HauntedPickaxeItem.wearMultiplier(tool)>1.49,"Wear increases pickaxe speed");var level=h.getLevel();var pos=p.blockPosition();HauntManager.setValue(level,pos,65);int before=HauntManager.getHundredths(level,pos),damage=tool.getDamageValue();HauntedPickaxeItem.repair(tool,level,pos,100);h.assertFalse(HauntedPickaxeItem.repair(tool,level,pos,139),"Repair respects tier interval");h.assertTrue(HauntedPickaxeItem.repair(tool,level,pos,140),"Eldritch repairs after forty ticks");h.assertTrue(tool.getDamageValue()==damage-1&&HauntManager.getHundredths(level,pos)==before-1,"Repair costs exactly .01 chunk haunt");HauntManager.setValue(level,pos,0);h.assertFalse(HauntedPickaxeItem.repair(tool,level,pos,10000),"Void never repairs");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void shovel_face_plane_and_connected_mining_respect_protection(GameTestHelper h){var p=player(h);try{
  var l=h.getLevel();var at=p.blockPosition();p.setGameMode(GameType.CREATIVE);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.BLOODSTONE_SHOVEL));for(int a=-1;a<=1;a++)for(int b=-1;b<=1;b++)l.setBlockAndUpdate(at.offset(0,a,b),Blocks.DIRT.defaultBlockState());l.setBlockAndUpdate(at.east(),Blocks.DIRT.defaultBlockState());DENIED.put(p.getUUID(),at.above());
  EquipmentMining.face(p,at,Direction.WEST,true);h.assertTrue(p.gameMode.destroyBlock(at),"Initial block breaks");EquipmentMining.tick(l);h.assertTrue(l.getBlockState(at.north()).isAir()&&l.getBlockState(at.below()).isAir(),"Clicked west face mines Y/Z plane");h.assertTrue(l.getBlockState(at.east()).is(Blocks.DIRT),"Plane does not follow player view direction");h.assertTrue(l.getBlockState(at.above()).is(Blocks.DIRT),"Actual Fabric cancellation protects neighbor");
  var start=at.offset(0,0,3);l.setBlockAndUpdate(start,Blocks.DIRT.defaultBlockState());l.setBlockAndUpdate(start.east(),Blocks.DIRT.defaultBlockState());l.setBlockAndUpdate(start.east(2),Blocks.DIRT.defaultBlockState());DENIED.put(p.getUUID(),start.east());p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.SPECTRALITE_SHOVEL));EquipmentMining.connected(p,start);EquipmentMining.tick(l);h.assertTrue(l.getBlockState(start).isAir(),"Charged harvest starts");h.assertTrue(l.getBlockState(start.east(2)).is(Blocks.DIRT),"Denied connected cell cannot bridge to next block");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void tree_felling_and_haunted_farmland_native_growth(GameTestHelper h){var p=player(h);try{
  var l=h.getLevel();var at=p.blockPosition();p.setGameMode(GameType.CREATIVE);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.BLOODSTONE_AXE));for(int y=0;y<4;y++)l.setBlockAndUpdate(at.above(y),Blocks.OAK_LOG.defaultBlockState());l.setBlockAndUpdate(at.above(4),Blocks.OAK_LEAVES.defaultBlockState());h.assertTrue(p.gameMode.destroyBlock(at),"Tree root harvested");EquipmentMining.tick(l);h.assertTrue(l.getBlockState(at.above(3)).isAir(),"Connected canopy-bearing tree felled");
  var soil=at.east(2);l.setBlockAndUpdate(soil,CatalogBlocks.HAUNTED_FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,0));l.setBlockAndUpdate(soil.above(),Blocks.WHEAT.defaultBlockState());HauntManager.setValue(l,soil,65);var farm=(HauntedFarmlandBlock)CatalogBlocks.HAUNTED_FARMLAND;farm.randomTick(l.getBlockState(soil),l,soil,l.random);h.assertTrue(l.getBlockState(soil).getValue(FarmBlock.MOISTURE)==7,"High haunt retains moisture");h.assertTrue(l.getBlockState(soil.above()).getValue(CropBlock.AGE)>0,"Eldritch random tick applies native bonemeal");h.assertTrue(HauntManager.getValue(l,soil)==65,"Passive soil growth consumes no haunt");h.assertTrue(l.getBlockState(soil).is(net.minecraft.tags.BlockTags.MINEABLE_WITH_SHOVEL),"Haunted soil remains shovel-mineable");h.assertTrue(Block.getDrops(l.getBlockState(soil),l,soil,null,p,new ItemStack(Items.DIAMOND_SHOVEL)).stream().anyMatch(stack->stack.is(Items.DIRT)),"Haunted soil retains ordinary dirt drops");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void scepter_recharge_and_real_allied_summons(GameTestHelper h){var p=player(h);try{
  var item=(PharaohlScepterItem)CatalogItems.PHARAOHL_SCEPTER;var stack=new ItemStack(item);var raw=new ItemStack(CatalogItems.RAW_ECTOPLASM,4);for(int i=0;i<3;i++)h.assertTrue(PharaohlScepterItem.recharge(stack,raw),"Raw recharges four uses");h.assertTrue(PharaohlScepterItem.charge(stack)==12&&raw.getCount()==1,"Three raw fill bar");h.assertFalse(PharaohlScepterItem.recharge(stack,raw),"Full bar does not consume ammo");p.setItemInHand(InteractionHand.MAIN_HAND,stack);h.assertTrue(item.use(h.getLevel(),p,InteractionHand.MAIN_HAND).getResult().consumesAction(),"Charged scepter summons allies");h.assertTrue(PharaohlScepterItem.charge(stack)==11&&p.getCooldowns().isOnCooldown(item),"One activation spends one twelfth and starts cooldown");var allies=h.getLevel().getEntitiesOfClass(com.howierux.mortalexpansion.entity.mob.MummyEntity.class,p.getBoundingBox().inflate(4));h.assertTrue(allies.size()==2,"Two mummy allies created");for(var ally:allies){h.assertTrue(p.getUUID().equals(ally.getAlliedOwner()),"Summoned mummy retains its owner");ally.setTarget(p);h.assertTrue(ally.getTarget()==null,"Summoned mummy cannot target its owner");ally.discard();}var pure=new ItemStack(CatalogItems.PURE_ECTOPLASM);stack.set(EquipmentRuntime.SCEPTER_CHARGE,0);h.assertTrue(PharaohlScepterItem.recharge(stack,pure)&&PharaohlScepterItem.charge(stack)==12,"One purified fully charges");
 }finally{remove(p);}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="equipment")
 public void native_respiration_and_paid_growth_abilities(GameTestHelper h){var p=player(h);try{
  equip(p,false);var l=h.getLevel();var at=p.blockPosition();var helmet=p.getItemBySlot(EquipmentSlot.HEAD);helmet.enchant(l.registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getHolderOrThrow(net.minecraft.world.item.enchantment.Enchantments.RESPIRATION),3);p.doTick();h.assertTrue(p.getAttributeValue(Attributes.OXYGEN_BONUS)>0,"Native Respiration enchantment grants oxygen bonus");
  l.setBlockAndUpdate(BlockPos.containing(p.getEyePosition()),Blocks.GLASS.defaultBlockState());int spent=0;for(int i=0;i<100;i++){p.setAirSupply(300);p.baseTick();spent+=300-p.getAirSupply();}h.assertTrue(spent>0&&spent<80,"Respiration reduces wall-air consumption, including glass");p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WATER_BREATHING,400));p.setAirSupply(200);p.baseTick();h.assertTrue(p.getAirSupply()==200,"Native water breathing also protects in walls");l.removeBlock(BlockPos.containing(p.getEyePosition()),false);
  var soil=at.east(2);l.setBlockAndUpdate(soil,CatalogBlocks.HAUNTED_FARMLAND.defaultBlockState().setValue(FarmBlock.MOISTURE,7));l.setBlockAndUpdate(soil.above(),Blocks.WHEAT.defaultBlockState());HauntManager.setValue(l,soil,65);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.SPECTRALITE_HOE));var cropHit=new BlockHitResult(soil.above().getCenter(),Direction.UP,soil.above(),false);h.assertTrue(SpectralCropGrowth.use(new UseOnContext(p,InteractionHand.MAIN_HAND,cropHit)).consumesAction(),"Spectral hoe invokes native bonemeal");h.assertTrue(((CropBlock)Blocks.WHEAT).isMaxAge(l.getBlockState(soil.above())),"One use grows wheat to maturity");h.assertTrue(HauntManager.getValue(l,soil)<65,"Successful crop pulses spend chunk haunt");
  var sapling=at.west(2);l.setBlockAndUpdate(sapling.below(),Blocks.DIRT.defaultBlockState());l.setBlockAndUpdate(sapling,Blocks.DARK_OAK_SAPLING.defaultBlockState());HauntManager.setValue(l,sapling,65);int before=HauntManager.getHundredths(l,sapling);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.SPECTRALITE_AXE));var saplingHit=new BlockHitResult(sapling.getCenter(),Direction.UP,sapling,false);h.assertTrue(SpectralSaplingGrowth.use(new UseOnContext(p,InteractionHand.MAIN_HAND,saplingHit)).consumesAction(),"Single dark oak safely stops after bounded attempts");h.assertTrue(l.getBlockState(sapling).is(Blocks.DARK_OAK_SAPLING)&&HauntManager.getHundredths(l,sapling)==before-10,"Failed tree formation pays only the initial .10 haunt");
 }finally{remove(p);}h.succeed();}
}
